def num(v):
    # JSON booleans and nonfinite values are not financial measurements.
    if type(v) not in (int, float, str) or isinstance(v, str) and len(v) > 512:
        return None
    try:
        value = float(v)
        return value if math.isfinite(value) else None
    except (ValueError, TypeError, OverflowError):
        return None


def first_num(*values):
    """Prefer the first available numeric observation, including genuine zero."""
    for value in values:
        result = num(value)
        if result is not None:
            return result
    return None

def finite_float(value):
    from decimal import Decimal
    parsed = float(value)
    if not math.isfinite(parsed) or parsed == 0 and Decimal(value) != 0:
        raise ValueError('Unrepresentable JSON number')
    return parsed
def finite_float(value):
    from decimal import Decimal
    if len(value) > 512:
        raise ValueError('Oversized JSON numeric token')
    exact = Decimal(value)
    parsed = float(value)
    if not math.isfinite(parsed) or Decimal(str(parsed)) != exact:
        raise ValueError('Lossy JSON numeric projection')
    return parsed
